/* HEXA BATTLEGROUNDS setup — PART 66 OF 83. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('airdrop-bomb-82', 'bomb', 'airdrop', 'Bomb Defusal', 'game', 1, array['any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, White, Black, Blue, Green, Black.\nSerial number: HX66A0.  LED: GREEN.","game":{"type":"bomb","wires":["green","white","black","blue","green","black"],"serial":"HX66A0","led":"green"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["3"]}]'::jsonb, false, 3, 150, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,white,black,blue,green,black · HX66A0 · green → override: If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual. → wire 3', null, 25, 'published'), ('airdrop-bomb-83', 'bomb', 'airdrop', 'Bomb Defusal', 'game', 2, array['any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, White, Green, Blue.\nSerial number: OM18Q4.  LED: BLUE.","game":{"type":"bomb","wires":["green","white","green","blue"],"serial":"OM18Q4","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the LED is BLUE and the first wire is YELLOW, cut the LAST wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["2"]}]'::jsonb, false, 3, 150, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,white,green,blue · OM18Q4 · blue → no yellow → second wire → wire 2', null, 25, 'published'), ('airdrop-bomb-84', 'bomb', 'airdrop', 'Bomb Defusal', 'game', 1, array['any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, Green, Black, White, Yellow, Red.\nSerial number: OM34K2.  LED: GREEN.","game":{"type":"bomb","wires":["black","green","black","white","yellow","red"],"serial":"OM34K2","led":"green"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are no RED wires at all, cut the wire just ABOVE the last one — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["6"]}]'::jsonb, false, 3, 150, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,green,black,white,yellow,red · OM34K2 · green → LED green → last wire → wire 6', null, 25, 'published'), ('airdrop-bomb-85', 'bomb', 'airdrop', 'Bomb Defusal', 'game', 1, array['any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, Blue, Green, Yellow.\nSerial number: SR90Q6.  LED: RED.","game":{"type":"bomb","wires":["green","blue","green","yellow"],"serial":"SR90Q6","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 150, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,blue,green,yellow · SR90Q6 · red → otherwise → first wire → wire 1', null, 25, 'published'), ('mission-signal-0', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["purple","green","white","green","green","purple","green"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 1\nGreen = 8\nBlue = 2\nYellow = 6\nPurple = 5\nWhite = 3"},"intel":{"title":"How to read it","body":"Read the flashes in REVERSE order (last flash first)."}}'::jsonb, '[{"label":"Code","accept":["8588385"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'purple,green,white,green,green,purple,green → green,purple,green,green,white,green,purple → 8588385', null, 25, 'published'), ('mission-signal-1', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["yellow","blue","green","white","red","red"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 2\nGreen = 4\nBlue = 8\nYellow = 5\nPurple = 2\nWhite = 5"},"intel":{"title":"How to read it","body":"Use only every SECOND flash (the 2nd, 4th, 6th…)."}}'::jsonb, '[{"label":"Code","accept":["852"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'yellow,blue,green,white,red,red → blue,white,red → 852', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-signal-2', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["red","yellow","yellow","green","green","green","yellow"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 4\nGreen = 7\nBlue = 3\nYellow = 2\nPurple = 8\nWhite = 4"},"intel":{"title":"How to read it","body":"Ignore every WHITE flash, then read the rest in order."}}'::jsonb, '[{"label":"Code","accept":["4227772"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'red,yellow,yellow,green,green,green,yellow → red,yellow,yellow,green,green,green,yellow → 4227772', null, 25, 'published'), ('mission-signal-3', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["red","white","green","purple","purple","white"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 6\nGreen = 3\nBlue = 6\nYellow = 1\nPurple = 5\nWhite = 3"},"intel":{"title":"How to read it","body":"Read them in order, but skip any colour you have already read once."}}'::jsonb, '[{"label":"Code","accept":["6335"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'red,white,green,purple,purple,white → red,white,green,purple → 6335', null, 25, 'published'), ('mission-signal-4', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["yellow","red","green","purple","purple","blue"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 4\nGreen = 5\nBlue = 1\nYellow = 7\nPurple = 5\nWhite = 5"},"intel":{"title":"How to read it","body":"Use only the first FOUR flashes, in order."}}'::jsonb, '[{"label":"Code","accept":["7455"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'yellow,red,green,purple,purple,blue → yellow,red,green,purple → 7455', null, 25, 'published'), ('mission-signal-5', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["red","white","green","green","yellow","green","red"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 3\nGreen = 2\nBlue = 2\nYellow = 6\nPurple = 5\nWhite = 5"},"intel":{"title":"How to read it","body":"Read the flashes in REVERSE order (last flash first)."}}'::jsonb, '[{"label":"Code","accept":["3262253"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'red,white,green,green,yellow,green,red → red,green,yellow,green,green,white,red → 3262253', null, 25, 'published'), ('mission-signal-6', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["white","white","white","red","purple","green","green"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 4\nGreen = 4\nBlue = 7\nYellow = 3\nPurple = 2\nWhite = 5"},"intel":{"title":"How to read it","body":"Use only every SECOND flash (the 2nd, 4th, 6th…)."}}'::jsonb, '[{"label":"Code","accept":["544"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'white,white,white,red,purple,green,green → white,red,green → 544', null, 25, 'published'), ('mission-signal-7', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":[